select * from jsonb_populate_recordset(null::public.recipes, $recipes$[{"id":"almuerzos-1-pastel-de-espinaca","numero":1,"titulo":"Pastel ligero de espinaca y quinua","categoria_id":"almuerzos","categoria_nombre":"Almuerzos","descripcion":"Pastel horneado de espinaca y quinua, húmedo por dentro y ligeramente gratinado.","imagen_principal":"/platos/almuerzo-corregido-01-pastel-ligero-de-espinaca-y-quinua.webp","tiempo_minutos":35,"dificultad":"Fácil","porciones":2,"nutricion":{"kcal":328,"carbs":33.6,"fibra":7.4,"sodio":309,"grasas":12.8,"proteina":26.2},"ingredientes":["250 g — Espinaca (1 manojo grande)","240 g — Quinua (1½ tazas cocidas)","100 g — Huevo (2 huevos)","100 g — Clara (3 claras)","120 g — Leche (½ taza)","30 g — Queso (2 cucharadas ralladas)","80 g — Cebolla (⅔ taza picada)","5 g — Aceite (1 cucharadita)"],"pasos":["Precalienta el horno a 180 °C y engrasa ligeramente una fuente.","Sofríe la cebolla con el aceite; añade la espinaca y cocina hasta que pierda volumen.","Mezcla huevos, claras y leche; incorpora quinua, espinaca y la mitad del queso.","Vierte en la fuente, termina con el queso restante y hornea 25 minutos hasta cuajar."],"tags":["Almuerzos","Receta auditada"],"tips_del_chef":["Deja reposar el pastel 8 minutos antes de cortarlo.","El queso va solo en la superficie para lograr aroma y gratinado con una cantidad pequeña."],"proteina_principal":{"id":"res","emoji":"🥩","nombre":"Res"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":1,"created_at":"2026-08-02T18:19:30.342872"},{"id":"snacks-1-pan-de-queso","numero":1,"titulo":"Bollitos horneados de queso","categoria_id":"snacks","categoria_nombre":"Snacks","descripcion":"Bollitos horneados de queso, reformulada con cantidades prácticas y grasa medida.","imagen_principal":"/platos/snacks-1-pan-de-queso.webp","tiempo_minutos":15,"dificultad":"Fácil","porciones":4,"nutricion":{"kcal":166.2,"carbs":11,"fibra":1.5,"sodio":240.5,"grasas":8.3,"proteina":11.7},"ingredientes":["Huevo 50 g","Mozzarella 100 g","Parmesano 30 g","Harina de avena 60 g"],"pasos":["Mezcla huevo, quesos y avena.","Forma ocho bollitos pequeños.","Hornea a 190 °C durante 12 a 15 minutos."],"tags":["low carb","keto-friendly","sin gluten","alto en proteína"],"tips_del_chef":["Cada porción equivale a dos bollitos."],"proteina_principal":{"id":"huevo","emoji":"🥚","nombre":"Huevo"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":1,"created_at":"2026-08-02T18:19:30.342872"},{"id":"meriendas-1-panini-de-queso-crema","numero":1,"titulo":"Pan plano individual de queso crema","categoria_id":"meriendas","categoria_nombre":"Meriendas","descripcion":"Pan plano individual de queso crema, reformulada con cantidades prácticas y grasa medida.","imagen_principal":"/platos/meriendas-1-panini-de-queso-crema.webp","tiempo_minutos":20,"dificultad":"Intermedio","porciones":2,"nutricion":{"kcal":214.6,"carbs":17.3,"fibra":2.2,"sodio":167.9,"grasas":11,"proteina":11.6},"ingredientes":["Huevo 100 g","Queso crema ligero 60 g","Harina de avena 40 g","Polvo de hornear 4 g"],"pasos":["Bate el huevo con el queso crema hasta integrar.","Añade harina de avena y polvo de hornear.","Divide en dos moldes planos y hornea a 180 °C durante 12 a 15 minutos."],"tags":["low carb","keto-friendly","sin gluten"],"tips_del_chef":["Usa papel de hornear; no es necesario engrasar el molde."],"proteina_principal":{"id":"huevo","emoji":"🥚","nombre":"Huevo"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":1,"created_at":"2026-08-02T18:19:30.342872"},{"id":"ensaladas-1-ensalada-de-berenjenas","numero":1,"titulo":"Ensalada tibia de berenjena y pimientos","categoria_id":"ensaladas","categoria_nombre":"Ensaladas","descripcion":"Ensalada tibia de berenjena y pimientos con ingredientes medidos y aliño equilibrado.","imagen_principal":"/platos/ensaladas-1-ensalada-de-berenjenas.webp","tiempo_minutos":15,"dificultad":"Fácil","porciones":4,"nutricion":{"kcal":126.9,"carbs":16.8,"fibra":6.6,"sodio":80.5,"grasas":5.3,"proteina":2.9},"ingredientes":["Berenjena en cubos 600 g","Cebolla en gajos 150 g","Pimiento rojo y amarillo 200 g","Aceitunas negras en rodajas 40 g","Ajo laminado 9 g","Albahaca fresca 15 g","Aceite de oliva 15 g"],"pasos":["Hornea la berenjena, la cebolla y los pimientos a 200 °C durante 25 minutos con el aceite medido.","Incorpora ajo y aceitunas; hornea 5 minutos más.","Entibia y termina con albahaca fresca."],"tags":["low carb","keto-friendly","vegetariana","sin gluten"],"tips_del_chef":["Mide el aceite antes de mezclar; una cucharada basta para toda la bandeja."],"proteina_principal":{"id":"vegetariana","emoji":"🥬","nombre":"Vegetariana"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":1,"created_at":"2026-08-02T18:19:30.342872"},{"id":"cenas-1-cangrejo-siri-con-champinones","numero":1,"titulo":"Cangrejo con champiñones y quinua","categoria_id":"cenas","categoria_nombre":"Cenas","descripcion":"Cangrejo con champiñones y quinua reúne cangrejo, champiñón y quinua. El plato se prepara mediante sartén y combina una proteína protagonista, vegetales con textura y un acompañamiento medido para formar un plato completo.","imagen_principal":"/platos/cenas-01-cangrejo-con-champinones-y-quinua.webp","tiempo_minutos":35,"dificultad":"Fácil","porciones":2,"nutricion":{"kcal":326,"carbs":30.5,"fibra":5.2,"sodio":504,"grasas":6.8,"proteina":36.3},"ingredientes":["Cangrejo: 280 g de carne de cangrejo cocida y limpia · 280 g","Quinua: 1⅔ tazas cocidas · 260 g","Champinon: 2½ tazas laminadas · 200 g","Cebolla: ⅔ taza picada · 80 g","Aceite: 1 cucharadita · 5 g","Leche: ½ taza · 120 g","Ajo: 1 diente pequeño · 3 g","Cúrcuma: ½ cucharadita · 1 g","Pimienta: 1 pizca · 0.5 g"],"pasos":["Cocina la quinua y reserva.","Calienta el aceite, cocina la cebolla y los champiñones hasta que pierdan parte de su agua.","Añade el ajo, la cúrcuma, la pimienta, el cangrejo cocido y la leche; calienta a fuego suave sin sobrecocer el cangrejo.","Reduce hasta obtener una salsa ligera y sirve con la quinua."],"tags":["#cenas","#proteina-cangrejo","#tecnica-sart-n","#receta-auditada"],"tips_del_chef":["Escurre bien los champiñones durante la cocción para que la salsa no quede aguada.","Añade el cangrejo al final y caliéntalo suavemente para conservar su textura."],"proteina_principal":{"id":"res","emoji":"🥩","nombre":"Res"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":1,"created_at":"2026-08-02T18:19:30.342872"},{"id":"sopas-y-cremas-1-crema-de-coliflor-con-puerros","numero":1,"titulo":"Crema de coliflor con poro y chayote","categoria_id":"sopas-y-cremas","categoria_nombre":"Sopas y cremas","descripcion":"Crema suave de coliflor, poro y chayote, terminada con hojas verdes y una cantidad medida de aceite.","imagen_principal":"/platos/sopas-y-cremas-1-crema-de-coliflor-con-puerros.webp","tiempo_minutos":30,"dificultad":"Fácil","porciones":4,"nutricion":{"kcal":98.8,"carbs":12.2,"fibra":4.6,"sodio":47.9,"grasas":3.6,"proteina":4.4},"ingredientes":["Coliflor en floretes 500 g (1 unidad pequeña)","Poro picado 100 g (1 taza)","Chayote pelado en cubos 300 g (2 unidades pequeñas)","Col crespa o espinaca picada 80 g (2 tazas)","Ajo 6 g (2 dientes)","Aceite vegetal u oliva 10 ml (2 cucharaditas)","Agua 800 ml (3 1/3 tazas)","Pimienta y nuez moscada al gusto","Sal opcional, medida: máximo 1/4 cucharadita para toda la olla"],"pasos":["Calienta el aceite en una olla y cocina el poro y el ajo 3 minutos a fuego medio.","Añade la coliflor, el chayote y el agua. Cocina tapado 18 a 20 minutos, hasta que las verduras estén tiernas.","Licúa con cuidado hasta obtener una crema homogénea.","Regresa a la olla, incorpora la col crespa y cocina 3 minutos. Ajusta la textura con agua caliente.","Sazona con pimienta, nuez moscada y, si se usa, la cantidad medida de sal."],"tags":["sopas y cremas","sin azúcar añadida"],"tips_del_chef":["Corta la coliflor y el chayote en tamaños similares para que se cocinen al mismo tiempo.","Licúa por tandas y deja una salida para el vapor si usas una licuadora de vaso."],"proteina_principal":{"id":"vegetariana","emoji":"🥬","nombre":"Vegetariana"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":1,"created_at":"2026-08-02T18:19:30.846388"},{"id":"postres-1-bizcochuelo-de-cacao","numero":1,"titulo":"Bizcochuelo de cacao","categoria_id":"postres","categoria_nombre":"Postres","descripcion":"Bizcochuelo húmedo de cacao y harina de coco, endulzado sin azúcar.","imagen_principal":"/platos/postres-1-bizcochuelo-de-cacao.webp","tiempo_minutos":35,"dificultad":"Fácil","porciones":8,"nutricion":{"kcal":66.6,"carbs":5.7,"fibra":3.2,"sodio":39.8,"grasas":3,"proteina":4.2},"ingredientes":["Huevos 3 unidades (150 g)","Harina de coco 50 g (1/2 taza)","Cacao sin azúcar 25 g (1/4 taza)","Eritritol granulado 40 g o estevia equivalente según etiqueta","Agua 120 ml (1/2 taza)","Polvo de hornear 5 g (1 cucharadita)","Vainilla 5 ml"],"pasos":["Precalienta el horno a 175 °C y forra un molde de 18 cm.","Separa claras y yemas. Bate las claras a punto de nieve.","Mezcla yemas, agua, vainilla y edulcorante.","Incorpora harina de coco, cacao y polvo de hornear.","Añade las claras en tres tandas y hornea 20 a 25 minutos."],"tags":["postres","sin azúcar añadida"],"tips_del_chef":["Rinde ocho porciones; deja enfriar antes de cortar.","La harina de coco absorbe mucho líquido: no aumentes la cantidad."],"proteina_principal":{"id":"huevo","emoji":"🥚","nombre":"Huevo"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":1,"created_at":"2026-08-02T18:19:30.342872"},{"id":"bebidas-1-batido-con-kefir","numero":1,"titulo":"Batido de kéfir, fresa y linaza","categoria_id":"bebidas","categoria_nombre":"Bebidas","descripcion":"Batido de kéfir, fresa y linaza combina kefir, fresa y leche en un vaso individual de textura y sabor definidos. La fórmula está ajustada como batido, sin azúcar añadida ni grasas concentradas innecesarias.","imagen_principal":"/platos/bebidas-01-batido-de-kefir-fresa-y-linaza.webp","tiempo_minutos":8,"dificultad":"Fácil","porciones":1,"nutricion":{"kcal":216,"carbs":23.5,"fibra":3.4,"grasas":9.2,"proteina":11.6},"ingredientes":["200 g/ml — Kefir (¾ taza)","100 g/ml — Fresa (¾ taza)","100 g/ml — Leche (⅓ taza)","5 g/ml — Linaza (1 cucharadita)","80 g/ml — Hielo (4 cubos)"],"pasos":["Lava y prepara todos los ingredientes.","Colócalos en la licuadora con el líquido y el hielo.","Licúa 45 a 60 segundos hasta obtener una textura uniforme.","Sirve inmediatamente en un vaso de 350 a 400 ml."],"tags":["#bebidas","#batido","#sin-azucar-anadida","#receta-auditada","Bebidas","Receta auditada"],"tips_del_chef":["Agita el kéfir antes de medirlo para integrar su textura.","Sirve batido de kéfir, fresa y linaza apenas termine el licuado para conservar su color y textura."],"proteina_principal":{"id":"vegetariana","emoji":"🥬","nombre":"Vegetariana"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":1,"created_at":"2026-08-02T18:19:30.342872"},{"id":"desayunos-1-torta-de-coco","numero":1,"titulo":"Bizcochito de avena, coco y plátano","categoria_id":"desayunos","categoria_nombre":"Desayunos","descripcion":"Bizcochito individual, húmedo y suavemente dulce, con avena, plátano y un toque de coco.","imagen_principal":"/platos/desayuno-corregido-01-bizcochito-de-avena-coco-y-platano.webp","tiempo_minutos":25,"dificultad":"Fácil","porciones":1,"nutricion":{"kcal":388,"carbs":53.3,"fibra":6.9,"sodio":211,"grasas":10.9,"proteina":24.9},"ingredientes":["40 g — Avena (½ taza)","120 g — Yogur (½ taza)","50 g — Huevo (1 huevo)","50 g — Clara (aprox. 2 claras pequeñas)","5 g — Coco (1 cucharada rasa)","50 g — Platano (½ plátano pequeño)","1 g — Canela (¼ cucharadita)"],"pasos":["Mezcla avena, yogur, huevo, clara y plátano aplastado.","Añade coco, canela y polvo de hornear.","Hornea 18 minutos a 180 °C en molde individual."],"tags":["Desayunos","Receta auditada"],"tips_del_chef":["No aumentes el coco: una pequeña cantidad es suficiente para aportar aroma.","Comprueba el centro con un palillo: debe salir con migas húmedas, no con masa líquida."],"proteina_principal":{"id":"huevo","emoji":"🥚","nombre":"Huevo"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":1,"created_at":"2026-08-02T18:19:30.342872"},{"id":"meriendas-2-panini-de-nueces","numero":2,"titulo":"Pan plano de nuez y linaza","categoria_id":"meriendas","categoria_nombre":"Meriendas","descripcion":"Pan plano de nuez y linaza, reformulada con cantidades prácticas y grasa medida.","imagen_principal":"/platos/meriendas-2-panini-de-nueces.webp","tiempo_minutos":20,"dificultad":"Fácil","porciones":2,"nutricion":{"kcal":248,"carbs":23.3,"fibra":5.1,"sodio":38.4,"grasas":13,"proteina":9.5},"ingredientes":["Huevo 50 g","Harina de nuez 20 g","Harina de linaza 10 g","Harina de avena 20 g","Agua 40 g"],"pasos":["Mezcla huevo, agua, nuez y linaza.","Deja reposar cinco minutos.","Forma dos panes finos y cocina en sartén antiadherente 3 minutos por lado."],"tags":["low carb","keto-friendly","sin gluten"],"tips_del_chef":["Mantén los panes finos para que el centro se cocine por completo."],"proteina_principal":{"id":"huevo","emoji":"🥚","nombre":"Huevo"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":2,"created_at":"2026-08-02T18:19:30.342872"},{"id":"snacks-2-mayonesa-de-aguacate","numero":2,"titulo":"Mayonesa ligera de palta","categoria_id":"snacks","categoria_nombre":"Snacks","descripcion":"Mayonesa ligera de palta, reformulada con cantidades prácticas y grasa medida.","imagen_principal":"/platos/snacks-2-mayonesa-de-aguacate.webp","tiempo_minutos":20,"dificultad":"Fácil","porciones":8,"nutricion":{"kcal":50.5,"carbs":2.8,"fibra":1.7,"sodio":7.5,"grasas":3.9,"proteina":1.1},"ingredientes":["Palta 200 g","Yogur natural 80 g","Jugo de limón 30 g","Ajo 3 g"],"pasos":["Procesa palta, yogur, limón y ajo.","Añade agua de una cucharada en una cucharada hasta ajustar la textura.","Refrigera y consume dentro de 24 horas."],"tags":["low carb","keto-friendly","vegetariana","sin gluten","rápida","sin horno"],"tips_del_chef":["La porción práctica es de aproximadamente 35 g; no requiere aceite adicional."],"proteina_principal":{"id":"vegetariana","emoji":"🥬","nombre":"Vegetariana"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":2,"created_at":"2026-08-02T18:19:30.342872"},{"id":"desayunos-2-crepe-clasico","numero":2,"titulo":"Crepe de avena con ricotta y fresas","categoria_id":"desayunos","categoria_nombre":"Desayunos","descripcion":"Crepes finos de avena rellenos con ricotta cremosa y fresas frescas.","imagen_principal":"/platos/desayuno-corregido-02-crepe-de-avena-con-ricotta-y-fresas.webp","tiempo_minutos":20,"dificultad":"Fácil","porciones":1,"nutricion":{"kcal":386,"carbs":45.8,"fibra":6.2,"sodio":265,"grasas":10.3,"proteina":31.9},"ingredientes":["40 g — Avena (½ taza molida)","50 g — Huevo (1 huevo)","80 g — Clara (aprox. 3 claras pequeñas)","80 g — Leche (⅓ taza)","60 g — Ricotta (¼ taza)","100 g — Fresa (1 taza)"],"pasos":["Licúa avena, huevo, claras y leche.","Cuaja dos crepes finos en sartén antiadherente.","Rellena con ricotta y fresas."],"tags":["Desayunos","Receta auditada"],"tips_del_chef":["Espera a que los bordes se despeguen antes de voltear.","Deja reposar la mezcla 5 minutos para que la avena se hidrate antes de cuajar los crepes."],"proteina_principal":{"id":"huevo","emoji":"🥚","nombre":"Huevo"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":2,"created_at":"2026-08-02T18:19:30.342872"},{"id":"bebidas-2-zumo-detox-con-limon-y-linaza","numero":2,"titulo":"Limonada de zanahoria y linaza","categoria_id":"bebidas","categoria_nombre":"Bebidas","descripcion":"Limonada de zanahoria y linaza combina limón, zanahoria y linaza en un vaso individual de textura y sabor definidos. La fórmula está ajustada como refrescante, sin azúcar añadida ni grasas concentradas innecesarias.","imagen_principal":"/platos/bebidas-02-limonada-de-zanahoria-y-linaza.webp","tiempo_minutos":8,"dificultad":"Fácil","porciones":1,"nutricion":{"kcal":90,"carbs":14,"fibra":5.1,"grasas":3.6,"proteina":2.5},"ingredientes":["30 g/ml — Limon (2 cucharadas de jugo)","100 g/ml — Zanahoria (1 zanahoria mediana)","8 g/ml — Linaza (2 cucharaditas)","250 g/ml — Agua (1 taza)","80 g/ml — Hielo (4 cubos)"],"pasos":["Lava y prepara todos los ingredientes.","Colócalos en la licuadora con el líquido y el hielo.","Licúa 45 a 60 segundos hasta obtener una textura uniforme.","Sirve inmediatamente en un vaso de 350 a 400 ml."],"tags":["#bebidas","#refrescante","#sin-azucar-anadida","#receta-auditada","Bebidas","Receta auditada"],"tips_del_chef":["Usa linaza recién molida para que se distribuya mejor.","Sirve limonada de zanahoria y linaza apenas termine el licuado para conservar su color y textura."],"proteina_principal":{"id":"vegetariana","emoji":"🌱","nombre":"Vegetariana"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":2,"created_at":"2026-08-02T18:19:31.03302"},{"id":"postres-2-tarta-de-avellana-y-chocolate","numero":2,"titulo":"Tarta de avellana y chocolate","categoria_id":"postres","categoria_nombre":"Postres","descripcion":"Tarta de avellana con cobertura fina de chocolate oscuro y naranja.","imagen_principal":"/platos/postres-2-tarta-de-avellana-y-chocolate.webp","tiempo_minutos":45,"dificultad":"Fácil","porciones":10,"nutricion":{"kcal":178.5,"carbs":7.5,"fibra":2.1,"sodio":31.9,"grasas":13.3,"proteina":7.2},"ingredientes":["Harina de avellanas 150 g","Proteína de suero neutra 30 g","Huevos 2 unidades (100 g)","Yogur natural descremado 120 g","Jugo de naranja 80 ml","Chocolate oscuro 70% 60 g","Leche de coco ligera 80 ml","Eritritol 40 g o estevia equivalente","Polvo de hornear 5 g","Ralladura de naranja 1 cucharadita"],"pasos":["Precalienta el horno a 175 °C y forra un molde de 18 cm.","Mezcla harina de avellanas, proteína y polvo de hornear.","Bate huevos, yogur, jugo, ralladura y edulcorante.","Integra ambas mezclas y hornea 25 a 30 minutos.","Derrite el chocolate con la leche de coco y extiende una capa fina sobre la tarta fría."],"tags":["postres","sin azúcar añadida"],"tips_del_chef":["Rinde diez porciones pequeñas.","La cobertura se limita a 6 g de chocolate por porción."],"proteina_principal":{"id":"huevo","emoji":"🥚","nombre":"Huevo"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":2,"created_at":"2026-08-02T18:19:30.342872"},{"id":"cenas-2-espagueti-de-zanahoria-con-albahaca","numero":2,"titulo":"Tallarines de zanahoria con pollo y albahaca","categoria_id":"cenas","categoria_nombre":"Cenas","descripcion":"Tallarines de zanahoria con pollo y albahaca reúne pollo, zanahoria y quinua. El plato se prepara mediante sartén y combina una proteína protagonista, vegetales con textura y un acompañamiento medido para formar un plato completo.","imagen_principal":"/platos/cenas-02-tallarines-de-zanahoria-con-pollo-y-albahaca.webp","tiempo_minutos":35,"dificultad":"Fácil","porciones":2,"nutricion":{"kcal":358,"carbs":34.4,"fibra":7.7,"sodio":161,"grasas":8.8,"proteina":35},"ingredientes":["280 g — Pollo (2 filetes medianos)","260 g — Quinua (1⅔ tazas cocidas)","250 g — Zanahoria (2 zanahorias grandes)","80 g — Cebolla (⅔ taza picada)","5 g — Aceite (1 cucharadita)"],"pasos":["Cocina quinua sin sal añadida y reserva.","Corta y cocina zanahoria hasta que quede tierna pero firme.","Calienta el aceite medido y cocina la cebolla; añade pollo y ajo, albahaca y pimienta hasta alcanzar cocción completa.","Integra los vegetales, ajusta la textura con agua si hace falta y sirve con el acompañamiento reservado."],"tags":["#cenas","#proteina-pollo","#tecnica-sart-n","#receta-auditada","Cenas","Receta auditada"],"tips_del_chef":["Para Tallarines de zanahoria con pollo y albahaca, corta zanahoria en piezas similares para que se cocine de manera uniforme.","Al preparar Tallarines de zanahoria con pollo y albahaca, mide 1 cucharadita de aceite antes de calentar; esa cantidad corresponde a toda la receta."],"proteina_principal":{"id":"res","emoji":"🥩","nombre":"Res"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":2,"created_at":"2026-08-02T18:19:30.342872"},{"id":"ensaladas-2-ensalada-de-mayonesa","numero":2,"titulo":"Ensalada cremosa de coliflor y huevo","categoria_id":"ensaladas","categoria_nombre":"Ensaladas","descripcion":"Ensalada cremosa de coliflor y huevo con ingredientes medidos y aliño equilibrado.","imagen_principal":"/platos/ensaladas-2-ensalada-de-mayonesa.webp","tiempo_minutos":15,"dificultad":"Intermedio","porciones":4,"nutricion":{"kcal":192.9,"carbs":10,"fibra":3.3,"sodio":169.3,"grasas":10.7,"proteina":14.2},"ingredientes":["Huevos cocidos 300 g","Coliflor en floretes 600 g","Yogur natural sin azúcar 120 g","Aceite de oliva 10 g","Jugo de limón 20 g","Cebollín picado 30 g"],"pasos":["Cocina la coliflor al vapor hasta que esté tierna pero firme; enfría.","Mezcla yogur, aceite medido, limón y cebollín.","Integra la coliflor y el huevo en trozos; refrigera 20 minutos."],"tags":["low carb","keto-friendly","sin gluten","rápida","sin horno"],"tips_del_chef":["El yogur reemplaza la crema y gran parte del aceite sin perder untuosidad."],"proteina_principal":{"id":"huevo","emoji":"🥚","nombre":"Huevo"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":2,"created_at":"2026-08-02T18:19:30.342872"},{"id":"almuerzos-2-bolitas-de-pollo","numero":2,"titulo":"Bolitas horneadas de pollo y coliflor","categoria_id":"almuerzos","categoria_nombre":"Almuerzos","descripcion":"Bolitas doradas de pollo y coliflor, ligadas con avena y cocidas al horno.","imagen_principal":"/platos/almuerzos-02-bolitas-horneadas-de-pollo-y-coliflor.webp","tiempo_minutos":35,"dificultad":"Fácil","porciones":2,"nutricion":{"kcal":364,"carbs":34.2,"fibra":8.1,"sodio":72,"grasas":11.4,"proteina":38.4},"ingredientes":["Pollo: 260 g de pollo molido crudo (aprox. 2 filetes medianos) · 260 g","Coliflor: 2½ tazas cocidas · 250 g","Avena: ⅔ taza molida · 60 g","Huevo: 1 huevo · 50 g","Cebolla: ½ taza picada · 60 g","Zanahoria: 1 taza rallada · 100 g","Aceite: 1 cucharadita · 5 g"],"pasos":["Precalienta el horno a 200 °C; cocina la coliflor, tritúrala y presiónala para retirar el exceso de agua.","Mezcla la coliflor con el pollo molido crudo, la avena, el huevo, la cebolla y la zanahoria.","Forma 12 bolitas iguales y colócalas en una bandeja pincelada con la cucharadita de aceite.","Hornea durante 25 minutos, voltéalas a mitad de cocción y comprueba que el pollo esté completamente cocido."],"tags":["low carb","keto-friendly","sin gluten"],"tips_del_chef":["Forma bolitas del mismo tamaño para que terminen de cocinarse juntas.","No añadas mayonesa: acompaña con yogur natural, limón y hierbas si deseas una salsa."],"proteina_principal":{"id":"pollo","emoji":"🍗","nombre":"Pollo"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":2,"created_at":"2026-08-02T18:19:30.342872"},{"id":"sopas-y-cremas-2-sopa-de-col-nutricional","numero":2,"titulo":"Crema verde de brócoli, coliflor y zapallito","categoria_id":"sopas-y-cremas","categoria_nombre":"Sopas y cremas","descripcion":"Crema de verduras verdes con brócoli, coliflor, zapallito italiano y espinaca, de textura suave y sabor fresco.","imagen_principal":"/platos/sopas-y-cremas-2-sopa-de-col-nutricional.webp","tiempo_minutos":30,"dificultad":"Fácil","porciones":4,"nutricion":{"kcal":121.7,"carbs":13.4,"fibra":5.7,"sodio":85.7,"grasas":4.5,"proteina":6.9},"ingredientes":["Brócoli en floretes 300 g (3 tazas)","Coliflor en floretes 400 g (4 tazas)","Zapallito italiano en rodajas 300 g (2 unidades medianas)","Espinaca 120 g (4 tazas)","Cebolla picada 100 g (1 unidad pequeña)","Ajo 6 g (2 dientes)","Aceite vegetal u oliva 10 ml (2 cucharaditas)","Agua 1 litro (4 tazas)","Pimienta al gusto","Sal opcional, máximo 1/4 cucharadita para toda la olla"],"pasos":["Calienta el aceite y cocina la cebolla y el ajo 3 minutos.","Añade el brócoli, la coliflor, el zapallito y el agua. Cocina 15 minutos.","Incorpora la espinaca y cocina 2 minutos más.","Licúa hasta obtener una crema uniforme y vuelve a calentar sin hervir.","Ajusta la consistencia y sazona."],"tags":["sopas y cremas","sin azúcar añadida"],"tips_del_chef":["Añade la espinaca al final para conservar mejor su color.","No prolongues la cocción después de licuar: basta con calentar la crema."],"proteina_principal":{"id":"vegetariana","emoji":"🥬","nombre":"Vegetariana"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":2,"created_at":"2026-08-02T18:19:30.846388"},{"id":"almuerzos-3-guiso-de-huevo","numero":3,"titulo":"Huevos guisados con tomate, garbanzos y verduras","categoria_id":"almuerzos","categoria_nombre":"Almuerzos","descripcion":"Huevos cocidos suavemente en salsa casera de tomate, pimiento y garbanzos.","imagen_principal":"/platos/almuerzo-corregido-03-huevos-guisados-con-tomate-garbanzos-y-verduras.webp","tiempo_minutos":25,"dificultad":"Fácil","porciones":2,"nutricion":{"kcal":419,"carbs":49.2,"fibra":12.9,"sodio":203,"grasas":14.6,"proteina":27.9},"ingredientes":["150 g — Huevo (3 huevos)","100 g — Clara (3 claras)","240 g — Garbanzo (1½ tazas cocidas)","300 g — Tomate (3 tomates medianos)","100 g — Cebolla (1 cebolla pequeña)","120 g — Pimiento (1 pimiento mediano)","5 g — Aceite (1 cucharadita)"],"pasos":["Sofríe cebolla y pimiento con el aceite durante 4 minutos.","Agrega tomate picado y garbanzos; cocina 8 minutos hasta formar una salsa.","Haz cavidades, añade huevos y claras, tapa y cocina a fuego bajo hasta que cuajen."],"tags":["Almuerzos","Receta auditada"],"tips_del_chef":["Tapa la sartén y cocina a fuego bajo para controlar el punto de las yemas.","Usa garbanzos cocidos sin sal o enjuaga muy bien los envasados."],"proteina_principal":{"id":"huevo","emoji":"🥚","nombre":"Huevo"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":3,"created_at":"2026-08-02T18:19:30.342872"},{"id":"snacks-3-crostinis-salados-de-granola","numero":3,"titulo":"Crostinis de plátano verde y linaza","categoria_id":"snacks","categoria_nombre":"Snacks","descripcion":"Crostinis de plátano verde y linaza, reformulada con cantidades prácticas y grasa medida.","imagen_principal":"/platos/snacks-3-crostinis-salados-de-granola.webp","tiempo_minutos":15,"dificultad":"Fácil","porciones":4,"nutricion":{"kcal":180.6,"carbs":23.3,"fibra":5.6,"sodio":5.5,"grasas":7.6,"proteina":4.7},"ingredientes":["Puré de plátano verde cocido 120 g","Harina de linaza 50 g","Harina de avena 60 g","Aceite de oliva 5 g"],"pasos":["Mezcla el puré con las harinas y el aceite.","Extiende fino entre dos hojas de papel y corta 12 piezas.","Hornea a 175 °C durante 20 minutos, volteando a mitad de cocción."],"tags":["low carb","keto-friendly","vegetariana","sin gluten","picante"],"tips_del_chef":["Cada porción equivale a tres crostinis."],"proteina_principal":{"id":"vegetariana","emoji":"🥬","nombre":"Vegetariana"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":3,"created_at":"2026-08-02T18:19:30.342872"},{"id":"desayunos-3-pan-casero-sin-gluten","numero":3,"titulo":"Panecillos de avena y quinua sin gluten","categoria_id":"desayunos","categoria_nombre":"Desayunos","descripcion":"Dos panecillos tiernos de avena y quinua, acompañados con ricotta.","imagen_principal":"/platos/desayuno-corregido-03-panecillos-de-avena-y-quinua-sin-gluten.webp","tiempo_minutos":35,"dificultad":"Fácil","porciones":1,"nutricion":{"kcal":450,"carbs":62.5,"fibra":9.3,"sodio":481,"grasas":10.7,"proteina":29.8},"ingredientes":["40 g — Avena (½ taza certificada sin gluten)","120 g — Quinua (¾ taza cocida)","50 g — Huevo (1 huevo)","50 g — Clara (aprox. 2 claras pequeñas)","60 g — Yogur (¼ taza)","60 g — Zanahoria (½ taza rallada)","40 g — Ricotta (3 cucharadas)","2 g — Polvo de hornear (½ cucharadita)"],"pasos":["Procesa avena, quinua, huevo, clara y yogur.","Integra la zanahoria y polvo de hornear.","Hornea dos panecillos 22 minutos a 180 °C y sirve con ricotta."],"tags":["Desayunos","Receta auditada"],"tips_del_chef":["Usa avena certificada si necesitas evitar contaminación con gluten.","Divide la mezcla en dos moldes iguales para que ambos panecillos se cocinen al mismo tiempo."],"proteina_principal":{"id":"huevo","emoji":"🥚","nombre":"Huevo"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":3,"created_at":"2026-08-02T18:19:30.342872"},{"id":"cenas-3-espaguetis-de-calabacin-01","numero":3,"titulo":"Tallarines de zapallito con pavita y tomate","categoria_id":"cenas","categoria_nombre":"Cenas","descripcion":"Tallarines de zapallito con pavita y tomate reúne pavita, zapallito italiano y quinua. El plato se prepara mediante sartén y combina una proteína protagonista, vegetales con textura y un acompañamiento medido para formar un plato completo.","imagen_principal":"/platos/cenas-03-tallarines-de-zapallito-con-pavita-y-tomate.webp","tiempo_minutos":35,"dificultad":"Fácil","porciones":2,"nutricion":{"kcal":340,"carbs":35.3,"fibra":7.7,"sodio":111,"grasas":7.3,"proteina":37.6},"ingredientes":["280 g — Pavita (2 filetes medianos)","260 g — Quinua (1⅔ tazas cocidas)","400 g — Zapallito (2 zapallitos medianos)","80 g — Cebolla (⅔ taza picada)","5 g — Aceite (1 cucharadita)","250 g — Tomate (2 tomates grandes)"],"pasos":["Cocina quinua sin sal añadida y reserva.","Corta y cocina zapallito hasta que quede tierna pero firme.","Calienta el aceite medido y cocina la cebolla; añade pavita y ajo y orégano hasta alcanzar cocción completa.","Integra los vegetales, ajusta la textura con agua si hace falta y sirve con el acompañamiento reservado."],"tags":["#cenas","#proteina-pavita","#tecnica-sart-n","#receta-auditada","Cenas","Receta auditada"],"tips_del_chef":["Para Tallarines de zapallito con pavita y tomate, corta zapallito italiano en piezas similares para que se cocine de manera uniforme.","Al preparar Tallarines de zapallito con pavita y tomate, mide 1 cucharadita de aceite antes de calentar; esa cantidad corresponde a toda la receta."],"proteina_principal":{"id":"vegetariana","emoji":"🥬","nombre":"Vegetariana"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":3,"created_at":"2026-08-02T18:19:30.342872"},{"id":"sopas-y-cremas-3-crema-de-castanas","numero":3,"titulo":"Crema fría de castañas de cajú y zanahoria","categoria_id":"sopas-y-cremas","categoria_nombre":"Sopas y cremas","descripcion":"Crema fría de zanahoria y castañas de cajú, con una porción moderada de frutos secos y acidez de limón.","imagen_principal":"/platos/sopas-y-cremas-3-crema-de-castanas.webp","tiempo_minutos":15,"dificultad":"Fácil","porciones":4,"nutricion":{"kcal":150,"carbs":10.2,"fibra":2.1,"sodio":23.6,"grasas":10.4,"proteina":3.9},"ingredientes":["Castañas de cajú sin sal 80 g (1/2 taza)","Zanahoria cocida y fría 200 g (2 unidades medianas)","Ajo 3 g (1 diente pequeño)","Jugo de limón 30 ml (2 cucharadas)","Agua fría 500 ml (2 tazas)","Pimienta al gusto","Sal opcional, máximo 1/8 cucharadita"],"pasos":["Cubre las castañas de cajú con agua y déjalas hidratar 4 horas en refrigeración. Escurre y enjuaga.","Licúa las castañas con la zanahoria, el ajo, el limón y 400 ml de agua.","Añade el agua restante poco a poco hasta lograr una textura ligera.","Refrigera 30 minutos y sirve fría."],"tags":["sopas y cremas","sin azúcar añadida"],"tips_del_chef":["El remojo debe realizarse en refrigeración para mantener la preparación segura.","No añadas aceite: las castañas de cajú ya aportan la cremosidad necesaria."],"proteina_principal":{"id":"vegetariana","emoji":"🥬","nombre":"Vegetariana"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":3,"created_at":"2026-08-02T18:19:30.846388"},{"id":"ensaladas-3-ensalada-de-calabacin-y-pollo","numero":3,"titulo":"Ensalada de zapallito italiano y pollo","categoria_id":"ensaladas","categoria_nombre":"Ensaladas","descripcion":"Ensalada de zapallito italiano y pollo con ingredientes medidos y aliño equilibrado.","imagen_principal":"/platos/ensaladas-3-ensalada-de-calabacin-y-pollo.webp","tiempo_minutos":20,"dificultad":"Fácil","porciones":4,"nutricion":{"kcal":240.3,"carbs":6.8,"fibra":2.3,"sodio":125.8,"grasas":8.1,"proteina":35.1},"ingredientes":["Pechuga de pollo cocida 400 g","Zapallito italiano 400 g","Tomate 200 g","Rúcula 80 g","Menta fresca 10 g","Queso fresco 40 g","Aceite de oliva 10 g","Jugo de limón 30 g"],"pasos":["Dora el zapallito en una sartén antiadherente y deja entibiar.","Corta el pollo y el tomate en porciones similares.","Mezcla todo con limón, aceite medido, rúcula y menta; termina con queso fresco."],"tags":["low carb","keto-friendly","sin gluten","picante","sin horno","alto en proteína"],"tips_del_chef":["Agrega la rúcula al final para conservar su textura."],"proteina_principal":{"id":"pollo","emoji":"🍗","nombre":"Pollo"},"estado":"GRATUITO","mostrar_a_pacientes":true,"visible":true,"orden":3,"created_at":"2026-08-02T18:19:30.342872"},{"id":"bebidas-3-jugo-detox-con-pimiento-rojo","numero":3,"titulo":"Jugo de tomate, pimiento y limón","categoria_id":"bebidas","categoria_nombre":"Bebidas","descripcion":"Bebida licuada de tomate y pimiento con limón, ligera y de sabor fresco.","imagen_principal":"/platos/bebidas-03-jugo-de-tomate-pimiento-y-limon.webp","tiempo_minutos":8,"dificultad":"Fácil","porciones":1,"nutricion":{"kcal":61,"carbs":13.9,"fibra":4,"sodio":0,"grasas":0.7,"proteina":2.7},"ingredientes":["Tomate: 2 tomates medianos","Pimiento: ½ pimiento","Limon: 2 cucharadas","Agua: ⅔ taza","Hielo: 4 cubos"],"pasos":["Lava y corta el tomate y el pimiento.","Licúa tomate, pimiento, limón, agua y hielo durante 45 segundos.","Sirve sin colar para conservar la pulpa."],"tags":["#bebidas","#refrescante","#sin-azucar-anadida","#receta-auditada"],"tips_del_chef":["Retira las semillas del pimiento si deseas una textura más suave.","No es necesario añadir aceite ni aderezo; el limón aport